    {
        var orig = ctx.Transport;
        var pipe = new Pipe();
        ctx.Transport = new Duplex(pipe.Reader, orig.Output);
        var pump = Pump(orig.Input, pipe.Writer);
        try { await next(ctx); }
        finally { ctx.Transport = orig; await pipe.Reader.CompleteAsync(); }
        try { await pump; } catch { }
    };

